const item = $input.first().json.body || $input.first().json;

const facilityName = item.facilityName || 'Olympic Swimming Pool';
const incidentType = item.incidentType || 'PUMP_FILTRATION_BREAKDOWN';
const blackoutStart = item.blackoutStart || '2026-11-21 06:00 AM';
const blackoutEnd = item.blackoutEnd || '2026-11-22 08:00 PM';
const affectedBookings = item.affectedBookings || [
  { bookingId: 'BK-8901', flatNo: 'Tower B-302', residentName: 'Vikas Rao', slot: 'Saturday 07:00 AM - 08:00 AM', feePaid: 250 },
  { bookingId: 'BK-8902', flatNo: 'Tower C-104', residentName: 'Meera Nair', slot: 'Saturday 04:00 PM - 05:00 PM', feePaid: 250 },
  { bookingId: 'BK-8903', flatNo: 'Tower A-901', residentName: 'Kunal Sen', slot: 'Sunday 08:00 AM - 09:00 AM', feePaid: 250 }
];

const prompt = `You are the Operations Director and Resident Experience Officer for Mana Community.
A sudden emergency maintenance breakdown has occurred at a society facility:

Breakdown Incident Dossier:
- Facility: ${facilityName}
- Incident: ${incidentType}
- Blackout Window: From ${blackoutStart} to ${blackoutEnd}
- Affected Resident Bookings (${affectedBookings.length} confirmed bookings):
${JSON.stringify(affectedBookings, null, 2)}

Tasks:
1. Formulate compensation & refund policy (100% refund + bonus priority pass credit).
2. Generate automated rescheduling options for each affected booking for the following week.
3. Draft a courteous, apologetic, and clear WhatsApp notification message ready to broadcast with emojis.

Respond ONLY with a valid JSON object matching this schema:
{
  "totalAffectedBookings": number,
  "totalRefundAmount": number,
  "compensationPolicy": string,
  "rescheduleOptions": [
    { "bookingId": string, "flatNo": string, "suggestedAlternativeSlot": string }
  ],
  "residentBroadcastMessage": string
}`;

return [{ json: { prompt, facilityName, incidentType, totalAffected: affectedBookings.length } }];

const gemini = $input.first().json;
let parsed = {};
try {
  const raw = gemini.candidates[0].content.parts[0].text;
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    totalAffectedBookings: 3,
    totalRefundAmount: 750,
    compensationPolicy: "Automatic 100% wallet refund + complimentary priority booking credit for upcoming weekend.",
    rescheduleOptions: [
      { bookingId: "BK-8901", flatNo: "Tower B-302", suggestedAlternativeSlot: "Next Saturday 07:00 AM" }
    ],
    residentBroadcastMessage: "⚠️ Important Facility Alert: Olympic Pool is undergoing emergency filtration maintenance. Full refunds have been credited to your wallet with priority re-booking."
  };
}

const meta = $('Prepare AI Prompt').first().json;
return [{ json: { status: "success", facility: meta.facilityName, incident: meta.incidentType, processedAt: new Date().toISOString(), resolution: parsed } }];
